const title=s=>s.replaceAll('_',' ').replace(/^./,x=>x.toUpperCase());
const pct=n=>(Number(n)*100).toFixed(2).replace(/\.00$/,'');
let tasks=[],demos=[],ablations={},reportFigures={};
const models=[['OpenWAM-α',55.32,.7005],['GPT-6-Astra · ICL',46.73,.6537],['Qwen-RobotManip',45.58,.6081],['π₀.₅',41.41,.5441],['InternVLA-A1.5',34.17,.4684],['π₀',33.72,.4748],['GigaBrain-0.7',33.27,.4603],['Fast-WAM',25.64,.3712]];
function video(path,label,detail,badge='Selected rollout'){return `<figure class="evidence-video"><div class="video-label"><strong>${label}</strong><span>${badge}</span></div><div class="media-viewport"><video playsinline preload="none" data-src="${path}" aria-label="${label}"></video><button class="video-start" aria-label="Play ${label}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 5v14l11-7z" fill="currentColor"/></svg></button></div><figcaption>${detail}</figcaption></figure>`;}
function mainVideo(task,seed,label,detail){let d=demos.find(x=>x.task===task&&x.seed===seed);return video(d.path,label,detail,`Episode ${seed} · ${d.sr?'Success':'Incomplete'} · Score ${d.score.toFixed(2)}`);}
function bars(groups){return reportChart(groups[0].startsWith('Mobile')?'mobility':groups[0].startsWith('Low')?'precision':'horizon');}
const section=(id,n,heading,sub,body)=>`<article class="finding" id="${id}"><div class="finding-inner"><div class="finding-heading"><span>${n}</span><div><h3>${heading}</h3></div></div>${body}</div></article>`;
const watch=text=>'';
function renderAnalysis(){
 $('#mobile-content').innerHTML=`<div class="finding-grid"><div class="finding-story"><div class="finding-metric"><strong>56.58<span>%</span></strong><p>SR on 19 mobile tasks</p></div><p>Only 3.60 percentage points behind OpenWAM-α, compared with a wider gap on tabletop tasks. Mobile manipulation is a relative strength compared with tabletop tasks.</p><div class="task-highlights"><button data-appendix="results"><strong>100<small>%</small></strong><span>Remote to holder · 20/20</span></button><button data-appendix="results"><strong>90<small>%</small></strong><span>Bookmark placement · 18/20</span></button></div><p class="fineprint">Bookmark SR is 35 pp above the next-best system. These are end-to-end task results, not isolated recognition measurements.</p></div>${reportChart('mobility')}</div><div class="evidence-pair">${mainVideo('remote_to_holder','000','Remote to holder','GPT-6-Astra 100% task SR; OpenWAM-α 65%. The selected episode succeeds.')}${mainVideo('bookmark_on_book','000','Bookmark placement','GPT-6-Astra 90% task SR; next-best π₀.₅ 55%. The selected episode succeeds.')}</div><p class="figure-caption">Selected main-cohort rollouts · GPT-6-Astra + ICL · Episode labels show backend terminal outcomes.</p>`;
 renderLimits('precision');
 $('#overall-content').innerHTML=`<div class="result-layout"><div class="result-summary"><p class="eyebrow">GPT-6-Astra + Single-shot In-Context Learning (ICL)</p><div class="overall-metric"><p class="metric-label">Task-averaged success rate</p><div class="metric-values"><strong class="metric-success">46.73<span>%</span></strong><span class="metric-score"><span>Score</span><b>0.6537</b></span></div></div><p class="benchmark-ranking">GPT-6-Astra <strong>ranks second on both metrics</strong>, behind only <strong>OpenWAM-α</strong>.</p><p class="fineprint">Equal-weight task means · Single-shot ICL throughout the main evaluation.</p></div><div class="table-scroll"><table class="leaderboard"><thead><tr><th>System</th><th>SR (%)</th><th>Score</th></tr></thead><tbody>${models.map(([n,s,c],i)=>`<tr class="${i===1?'highlight':''}"><td><span class="rank">${i+1}</span>${n}</td><td>${i===0?'<b>':''}${s.toFixed(2)}${i===0?'</b>':''}</td><td>${i===0?'<b>':''}${c.toFixed(4)}${i===0?'</b>':''}</td></tr>`).join('')}</tbody></table><p class="fineprint">Equal-weight task means. Highlight identifies GPT-6-Astra; bold values mark the best system.</p></div></div>${reportChart('overall')}`;
 initVideos();initCharts();}
function renderLimits(kind){const precision=kind==='precision';$('#limits-content').innerHTML=`<div class="finding-grid"><div class="finding-story"><div class="finding-metric"><strong>${precision?'11.25':'28.10'}<span>%</span></strong><p>${precision?'SR on high-precision tasks':'SR on long-horizon tasks'}</p></div><p>${precision?'GPT-6-Astra’s SR falls from 60.60% on low-precision tasks to 11.25% on high-precision tasks. On peg insertion, 0.6000 mean Score accompanies only 20% success.':'GPT-6-Astra reaches 53.60% SR on short tasks but 28.10% on long tasks. OpenWAM-α retains 51.43% on the long-horizon group.'}</p><p>${precision?'Transport and approach can succeed while final alignment remains unresolved. The two peg episodes show the difference between substantial progress and a completed insertion.':'Local retries can repair one step while later stages remain unfinished. The selected dishwasher rollout is GPT-6-Astra’s only success among 20 episodes.'}</p><button class="appendix-link" data-appendix="${precision?'attributes':'horizon'}">Explore the group results ↗</button></div>${reportChart(precision?'precision':'horizon')}</div><div class="evidence-pair">${precision?mainVideo('peg_in_hole','000','Peg insertion · incomplete','Terminal Score 0.50. The peg remains exposed.')+mainVideo('peg_in_hole','002','Peg insertion · success','Terminal Score 1.00. One of four successes in 20 task instances.'):mainVideo('bottle','003','Bottle placement · partial progress','Terminal Score 0.50. Some bottles remain outside the tray.')+mainVideo('dishwasher','011','Dishwasher · successful instance','Terminal Score 1.00. Only one success in 20 GPT-6-Astra episodes.')}</div>`;updateLimitNarrative(kind);initVideos();initCharts();enhanceEvidence($('#limits-content'));}
const cases=[{id:'poc',n:'04 / COMPOSITION',title:'Unseen task composition',sub:'Independent zero-shot POC'},{id:'recovery',n:'01 / RECOVERY',title:'Revisit a disrupted goal',sub:'GPT-6-Astra · π₀.₅ · OpenWAM'},{id:'icl',n:'02 / IN-CONTEXT LEARNING',title:'Learn the operation from an example',sub:'Zero-shot vs. demonstration'},{id:'fine',n:'03 / PRECISE EXECUTION',title:'Inspect the final contact',sub:'GPT-6-Astra · π₀.₅ · OpenWAM'}];
cases.push(cases.shift());
let activeCase='recovery',iclTask='frame';
function renderCase(){ $('#case-tabs').innerHTML=cases.map(c=>`<button role="tab" id="tab-${c.id}" aria-controls="case-content" aria-selected="${activeCase===c.id}" tabindex="${activeCase===c.id?0:-1}" data-case="${c.id}" class="case-tab ${activeCase===c.id?'active':''}"><span>${c.n}</span><strong>${c.title}</strong><small>${c.sub}</small></button>`).join('');$('#case-content').setAttribute('aria-labelledby','tab-'+activeCase);let html='';if(activeCase==='poc'){renderPoc();return;}if(activeCase==='icl'){let frame=iclTask==='frame';html=`<div class="case-heading"><div><p class="eyebrow">ICL / TASK-SPECIFIC MANIPULATION</p><h3>${frame?'The demonstration changes the grasp.':'From lifting a gear to placing it.'}</h3></div><div class="segmented" aria-label="ICL task"><button data-icl="frame" aria-pressed="${frame}">Photo frame</button><button data-icl="gear" aria-pressed="${!frame}">Install gear</button></div></div><p class="case-description">${frame?'Without a demonstration, GPT-6-Astra reaches and moves the frame, but repeated wrist adjustments do not complete the task. With ICL, a more appropriate grasp and coordinated use of both grippers lead to placement on the pen holder.':'The zero-shot rollout lifts the gear but leaves it outside the intended assembly position. The ICL example guides it between the existing gears, lowers it into place, and releases it.'}</p><div class="evidence-pair case-videos">${video(`media/cases/zero-shot-${iclTask}.mp4`,'Zero-shot','No demonstration · selected qualitative example','No demo')}${video(`media/cases/icl-${iclTask}.mp4`,'In-context learning','Demonstration-conditioned · selected qualitative example','With demo')}</div><div class="case-insight"><p>${frame?'In this example, the demonstration provides grasp orientation and the division of work between the two arms.':'The successful rollout follows a placement geometry and operation sequence appropriate to the gear assembly.'}</p><div class="icl-case-links"><button class="appendix-link" data-icl-package="${frame?'frame_against_pen_holder':'install_gear'}">Inspect the complete demonstration ↗</button><button class="appendix-link" data-appendix="ablation">Explore the paired ICL experiments ↗</button></div></div>`;}else{let fine=activeCase==='fine',suffix=fine?'glasses':'teacup';html=`<div class="case-heading"><div><p class="eyebrow">AGENT / VLA / WAM</p><h3>${fine?'The last step makes the difference.':'A displaced cup becomes a goal again.'}</h3></div><span class="qualitative-label">Selected rollouts · qualitative comparison</span></div><p class="case-description">${fine?'The subsequent folding and closure expose a sharper difference: GPT-6-Astra leaves the temples protruding, π₀.₅ folds them with the lid still open, and OpenWAM closes the case.':'GPT-6-Astra revises its grasp and later returns to the cup after it is displaced. In the selected π₀.₅ rollout, the cup transfer remains unresolved; OpenWAM moves the teapot while leaving the cup off the saucer.'}</p><div class="evidence-trio case-videos">${[['astra','GPT-6-Astra · Agent + ICL',fine?'Temples protrude; closure remains obstructed.':'Regrasp and return after the cup is displaced.'],['pi05','π₀.₅ · VLA',fine?'Temples folded; lid remains open.':'Repeated approach; cup transfer unresolved.'],['openwam','OpenWAM · WAM',fine?'Temples folded and case closed.':'Teapot transferred; cup goal remains unmet.']].map(([file,name,desc])=>video(`media/cases/${file}-${suffix}.mp4`,name,desc,'Observed outcome')).join('')}</div><div class="stage-controls"><span>Inspect a stage</span>${(fine?['Initial state','Transfer','Adjustment','Outcome']:['Initial state','Approach','Task progress','Outcome']).map((s,i)=>`<button data-stage="${i}">${s}</button>`).join('')}</div><p class="fineprint">Stages use each video’s own report timestamp. Playback time is not inference latency; object variants and viewpoints differ.</p><div class="case-insight"><p>${fine?'GPT-6-Astra performs the initial transfer, but the protruding temples obstruct lid closure. The specialized policies execute the folding more accurately in these selected rollouts.':'The selected GPT-6-Astra rollout responds to an invalidated task state by revisiting the cup. This behavior is not captured by observing only the initial placement.'}</p><button class="appendix-link" data-appendix="case-notes">Case annotations & interpretation ↗</button></div>`;}$('#case-content').innerHTML=html;updateCaseNarrative();initVideos();enhanceCaseControls();}
const notes={
protocol:['Evaluation protocol',`<p>GPT-6-Astra uses reasoning effort <code>high</code>. Each episode starts with a fresh model thread; recovery may reconstruct a thread from confirmed history and current observations.</p><p>Initial inputs: overview, left-wrist, and right-wrist RGB views, end-effector poses, gripper state, base pose, and simulator timestep. Later calls return requested camera subsets.</p><p>Live observations exclude depth, ground-truth object poses, camera calibration, segmentation, intermediate scores, and subgoal signals. No learned VLA or WAM refines GPT-6-Astra’s action requests.</p><p>The same task-specific physics horizons and camera restrictions apply. No additional aggregate token, tool-call, or wall-clock limit is imposed on the main policy phase. Automatic holding may continue simulation until terminal evaluation.</p>`],
metrics:['What the numbers mean',`<p><b>SR</b> measures server-side complete success. <b>Score</b> is normalized terminal partial credit under task-specific rules.</p><p>Headline values average 26 task means equally: SR 46.73%, Score 0.6537. There are 237 successes among 510 retained episodes; episode-weighted SR is 46.47%.</p><p>24 tasks have 20 instances; make_sandwich and microwave have 15 each. Attribute groups overlap and do not represent paired changes to identical tasks.</p>`],
attributes:['Task-attribute profiles',`${reportChart('precision')}${reportChart('mobility')}${reportChart('horizon')}<p>Precision: 14 low / 8 medium / 4 high tasks. Mobility: 19 mobile / 7 tabletop. Horizon: 19 short / 7 long. Groups overlap.</p><p>Lines connect category means, not controlled changes to the same task.</p><button class="appendix-link" data-appendix="results">View per-task results ↗</button>`],
horizon:['Long-horizon results and execution',`<p>GPT-6-Astra long-horizon SR is 28.10%, Score 0.5994; OpenWAM-α reaches 51.43% and 0.7872.</p><p>Detergent: GPT-6-Astra 55% SR / 0.8000 Score; OpenWAM 95% SR. Dishwasher: GPT-6-Astra 5% / 0.5333; OpenWAM 90% SR.</p><p>The agent sees elapsed timestep without a numeric remaining-step budget. A waypoint batch delays the next observation until the batch returns. These conditions motivate examining retries and feedback timing; they do not establish that more time resolves failures.</p><p>Bottle and shop have zero complete successes across all eight systems.</p>`],
behavior:['Behavioral evidence: context matters',`<h3>Contact correction · coffee beans / 013</h3><blockquote>“Angle spoon edge down to tabletop behind beans”</blockquote><p>This public action description accompanies height and tilt adjustments. Terminal Score 0.5, SR 0. The supplied prompt already warns that local EEF z is not tabletop height; the record does not establish measured table height or intended contact.</p><h3>Task–reference alignment · fruit / 015</h3><blockquote>“Carry the secured fruit above the small cup, not the large jug.”</blockquote><p>The live instruction requests a milkshake in the cup; the historical example uses a jug and explicitly defers to the live instruction. Score 0.6, SR 0. This illustrates role reconciliation, not refusal to follow guidance.</p><h3>Exploration and recovery</h3><p>Approach and grasp revisions are observed within episodes. The selected cases illustrate behavior, not a measured recovery advantage or improvement across episodes.</p>`],
'case-notes':['Reading the case studies',`<p>These are selected qualitative rollouts, not a matched statistical recovery evaluation. Object variants and viewpoints differ.</p><p>Captions describe visible states. The draft’s local score badges are not treated here as independently verified backend success labels.</p><p>Stage timestamps follow Figure 5. They align semantic phases, not inference cost.</p><p>POC is an independent unseen-composition evaluation, outside the 26-task main cohort. Comparison policies are retrained on constituent atomic skills. The evaluation task combinations are unseen and no test-time demonstration is supplied.</p>`],
limitations:['Scope and limitations',`<p>The main cohort uses ICL throughout; it does not measure demonstration gains alone. Exploratory comparisons are reported separately.</p><p>Task-attribute correlations do not isolate causes. Selected videos do not measure failure-mode frequency. A server success label need not establish every visually desirable final state.</p><p>Simulation horizons are held constant, not inference cost. Hardware safety, real deployment, and recursive improvement across episodes are not directly tested.</p><p>This is the supplied September 2026 snapshot, not a continuously updated leaderboard.</p>`]
};
function openAppendix(key){if(key==='icl'){openICLPackage();return;}$('#appendix-dialog').dataset.content=key;$('#appendix-dialog').classList.remove('icl-dialog');let content=notes[key];if(key==='generalization')content=['Across benchmark perturbations',kitComparisonTable('generalization')];if(key==='full-comparison')content=['All systems and task groups',kitComparisonTable('main')];if(key==='results')content=['Task-level results & video evidence',taskResultsMarkup()];if(key==='ablation')content=pairedICLContent();if(!content)return;$('#appendix-body').innerHTML=`<h2 id="appendix-title">${content[0]}</h2>${content[1]}`;if(!$('#appendix-dialog').open)$('#appendix-dialog').showModal();$('#appendix-body').scrollTop=0;initCharts();initTaskTable();}
const observer=new IntersectionObserver(entries=>entries.forEach(({target,isIntersecting})=>{if(isIntersecting&&!target.getAttribute('src')){target.src=target.dataset.src+'#t=0.1';target.preload='metadata';}if(!isIntersecting)target.pause();}),{rootMargin:'200px'});
function initVideos(){document.querySelectorAll('video[data-src]').forEach(v=>{if(v.dataset.bound)return;v.dataset.bound='true';observer.observe(v);v.addEventListener('error',()=>{if(!v.parentElement.querySelector('.video-error'))v.insertAdjacentHTML('afterend','<p class="video-error">Recording could not load. <a href="'+v.dataset.src+'" target="_blank">Open video directly ↗</a></p>');});});}
function changeCase(){document.querySelectorAll('#case-content video').forEach(v=>{v.pause();observer.unobserve(v);});renderCase();}
document.addEventListener('click',e=>{let el=e.target.closest('[data-appendix]');if(el)openAppendix(el.dataset.appendix);el=e.target.closest('[data-case]');if(el){activeCase=el.dataset.case;changeCase();$('#tab-'+activeCase).focus();}el=e.target.closest('[data-icl]');if(el){iclTask=el.dataset.icl;changeCase();}el=e.target.closest('[data-stage]');if(el){let times=activeCase==='fine'?[[0,14,46,100],[0,26,51,100],[0,26,49,70.4]]:[[0,8.9,38.5,47],[0,6,29,66.7],[0,7,35,66.7]];$('#case-content').querySelectorAll('video').forEach((v,i)=>{if(!v.src)v.src=v.dataset.src;const seek=()=>{v.pause();v.controls=true;const overlay=v.closest('.media-viewport')?.querySelector('.video-start');if(overlay)overlay.hidden=true;v.currentTime=Math.min(times[i][Number(el.dataset.stage)],Number.isFinite(v.duration)?v.duration-.05:Infinity);};if(v.readyState>=1)seek();else v.addEventListener('loadedmetadata',seek,{once:true});});document.querySelectorAll('[data-stage]').forEach(b=>b.classList.toggle('active',b===el));}el=e.target.closest('[data-task-video]');if(el){let d=demos.find(x=>x.task===el.dataset.taskVideo);$('#appendix-body').innerHTML=`<button class="appendix-link" data-appendix="results">← All task results</button><h2 id="appendix-title">${title(d.task)}</h2>${mainVideo(d.task,d.seed,'GPT-6-Astra · ICL','Selected task example; aggregate results describe task-level performance.')}<p class="fineprint">Episode ${d.seed} · Terminal SR ${d.sr} · Score ${d.score}</p>`;if(!$('#appendix-dialog').open)$('#appendix-dialog').showModal();initVideos();}});
$('#case-tabs').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();let i=cases.findIndex(c=>c.id===activeCase);i=e.key==='Home'?0:e.key==='End'?cases.length-1:(i+(e.key==='ArrowRight'?1:-1)+cases.length)%cases.length;activeCase=cases[i].id;changeCase();$('#tab-'+activeCase).focus();});
$('.close-dialog').addEventListener('click',()=>$('#appendix-dialog').close());$('#appendix-dialog').addEventListener('click',e=>{if(e.target===$('#appendix-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});$('#appendix-dialog').addEventListener('close',()=>$('#appendix-dialog').querySelectorAll('video').forEach(v=>v.pause()));
Promise.all(['tasks','demo-videos','ablations','report-figures'].map(n=>fetch('data/'+n+'.json').then(r=>{if(!r.ok)throw Error(n);return r.json();}))).then(([t,d,a,r])=>{tasks=t;demos=d;ablations=a;reportFigures=r;reportFigures.models.forEach(m=>{if(m.id==='Astra (ICL)')m.label='GPT-6-Astra (ICL)';if(m.id==='FastWAM')m.label='Fast-WAM';});renderAnalysis();renderCase();initReportLayout();initResearch();initNarrative();initShowcase();}).catch(()=>{$('#mobile-content').innerHTML='<p>Benchmark data could not load. Please reload the page.</p>';});
// Enlarge one camera pane without altering the original recording.
function enhanceCameraView(v){if(v.videoWidth/v.videoHeight<4||v.dataset.cameraReady)return;v.dataset.cameraReady='true';v.dataset.view='center';const bar=document.createElement('div');bar.className='camera-controls';bar.setAttribute('aria-label','Recording view');bar.innerHTML='<span>Camera view</span>'+[['left','Left'],['center','Center'],['right','Right'],['all','All three']].map(([key,name])=>`<button data-camera="${key}" aria-pressed="${key==='center'}">${name}</button>`).join('');(v.closest('.media-viewport')||v).insertAdjacentElement('afterend',bar);}
document.addEventListener('loadedmetadata',e=>{if(e.target.tagName==='VIDEO')enhanceCameraView(e.target);},true);
document.querySelectorAll('video').forEach(v=>{if(v.readyState)enhanceCameraView(v);});
document.addEventListener('click',e=>{const b=e.target.closest('[data-camera]');if(!b)return;const bar=b.parentElement,previous=bar.previousElementSibling,v=previous.tagName==='VIDEO'?previous:previous.querySelector('video');v.dataset.view=b.dataset.camera;bar.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));});

function initReportLayout(){
 const overall=$('#overall-content'),table=overall.querySelector('.result-layout>.table-scroll'),chart=overall.querySelector('[data-chart="overall"]');
 const panel=document.createElement('div');panel.className='result-panel';panel.innerHTML='<div class="result-panel-header"><div><span class="component-kicker">EIGHT SYSTEMS · SAME BENCHMARK</span><h4>Comparison across models</h4></div><div class="view-switch" aria-label="Results presentation"><button data-result-view="table" aria-pressed="false">Table</button><button data-result-view="chart" aria-pressed="true">Chart</button></div></div><div class="result-panel-body"></div>';overall.querySelector('.result-layout').append(panel);panel.querySelector('.result-panel-body').append(table,chart);table.hidden=true;chart.hidden=false;
 panel.addEventListener('click',e=>{const b=e.target.closest('[data-result-view]');if(!b)return;const show=b.dataset.resultView==='chart';table.hidden=show;chart.hidden=!show;panel.querySelectorAll('[data-result-view]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));});enhanceEvidence(document);
}
function enhanceEvidence(root){root.querySelectorAll('.evidence-pair:not(.case-videos)').forEach(pair=>{if(pair.closest('.evidence-stage'))return;const stage=document.createElement('div');stage.className='evidence-stage';pair.before(stage);stage.innerHTML='<div class="evidence-stage-heading"><span>OBSERVE THE EXECUTION</span><button class="play-group" aria-pressed="false">Play both <span aria-hidden="true">▷</span></button></div>';stage.append(pair);});}
document.addEventListener('click',async e=>{const b=e.target.closest('.play-group');if(!b)return;const videos=[...b.closest('.evidence-stage').querySelectorAll('video')];const play=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',String(play));b.innerHTML=play?'Pause both <span aria-hidden="true">Ⅱ</span>':'Play both <span aria-hidden="true">▷</span>';for(const v of videos){if(play){v.muted=true;if(!v.src)v.src=v.dataset.src;try{await v.play();}catch{b.setAttribute('aria-pressed','false');b.textContent='Play both ▷';}}else v.pause();}});

document.addEventListener('click',async e=>{const b=e.target.closest('.video-start');if(!b)return;const v=b.parentElement.querySelector('video');v.controls=true;try{await v.play();}catch{v.controls=true;b.hidden=true;}});
document.addEventListener('play',e=>{if(e.target.tagName!=='VIDEO')return;e.target.controls=true;const b=e.target.closest('.media-viewport')?.querySelector('.video-start');if(b)b.hidden=true;},true);

for(const event of ['play','pause','ended'])document.addEventListener(event,e=>{if(e.target.tagName!=='VIDEO')return;const stage=e.target.closest('.evidence-stage');if(!stage)return;const playing=[...stage.querySelectorAll('video')].some(v=>!v.paused&&!v.ended),button=stage.querySelector('.play-group');button.setAttribute('aria-pressed',String(playing));button.innerHTML=playing?'Pause both <span aria-hidden="true">Ⅱ</span>':'Play both <span aria-hidden="true">▷</span>';},true);
